custom_css:
/* MG5 visual parity */
.mg5-demo-navigation{position:sticky;top:0;z-index:20;line-height:1.4}
.mg5-subnav{display:flex;align-items:center;justify-content:space-between;gap:28px;min-height:85px;padding:16px clamp(20px,5.8vw,76px);background:#737577;color:#fff;font-family:Arial,Helvetica,sans-serif}
.mg5-subnav a{color:#fff;text-decoration:none;white-space:nowrap}
.mg5-subnav__brand{flex:0 0 auto;font-size:22px;font-weight:700;letter-spacing:.02em}
.mg5-subnav__links{display:flex;align-items:center;justify-content:flex-end;gap:32px;min-width:0;font-size:15px}
.mg5-subnav__cta{padding:10px 20px;border-radius:999px;background:#d71920}
@media(max-width:900px){.mg5-subnav{align-items:flex-start;flex-direction:column;gap:12px;min-height:0;padding-block:14px}.mg5-subnav__links{width:100%;justify-content:flex-start;gap:22px;overflow-x:auto;scrollbar-width:none}}
#mg5-overview,#mg5-design,#mg5-performance{scroll-margin-top:85px}
@media(max-width:900px){#mg5-overview,#mg5-design,#mg5-performance{scroll-margin-top:132px}}
.pb-canvas.is-tablet .mg5-subnav,.pb-canvas.is-mobile .mg5-subnav{align-items:flex-start;flex-direction:column;gap:12px;min-height:0;padding:14px 20px}
.pb-canvas.is-tablet .mg5-subnav__links,.pb-canvas.is-mobile .mg5-subnav__links{width:100%;justify-content:flex-start;gap:22px;overflow-x:auto;scrollbar-width:none}
.mg5-subnav__links::-webkit-scrollbar{display:none}
.mg5-subnav__links{scrollbar-width:none}

/* MG5 full specifications extension */
#mg5-specification,#mg5-price,#mg5-colors,#mg5-services{scroll-margin-top:85px}
#mg5-specification .pb-feature-showcase__container{padding-top:94px;padding-bottom:28px}
#mg5-specification .pb-feature-showcase__hero-heading{margin-bottom:54px}
#mg5-specification .pb-feature-showcase__hero-heading .pb-feature-showcase__title{margin-bottom:14px}
#mg5-specification .pb-feature-showcase__split--hero{align-items:center;min-height:390px}
#mg5-specification .pb-feature-showcase__metrics{gap:62px}
#mg5-specification .pb-feature-showcase__metric-label{margin-bottom:4px}
#mg5-specification .pb-feature-showcase__media img{height:auto;max-height:435px;object-fit:contain}
#mg5-spec-tabs{width:min(calc(100% - 40px),1296px);margin:0 auto;padding:4px 0 62px}
#mg5-spec-tabs .el-widget-tabs__nav{border-bottom:1px solid #d9d9d9}
#mg5-spec-tabs .el-widget-tabs__title{flex:1 1 0}
#mg5-spec-tabs .el-tabs-content{padding-top:28px}
#mg5-spec-tabs .el-widget-accordion__summary{min-height:60px;padding:16px 25px}
#mg5-spec-tabs .el-widget-accordion__item{overflow:hidden}
#mg5-spec-tabs .el-widget-accordion__content{padding:0!important}
.mg5-spec-table{width:100%}
.mg5-spec-row{display:grid;grid-template-columns:minmax(0,1.45fr) minmax(180px,.55fr);gap:32px;align-items:start;padding:13px 0;border-bottom:1px solid #ededed;font-size:14px;line-height:1.45}
.mg5-spec-row:last-child{border-bottom:0}
.mg5-spec-label{display:flex;align-items:flex-start;gap:11px;color:#3b3b3b}
.mg5-spec-label i{flex:0 0 auto;margin-top:2px;color:#28a745;font-size:16px}
.mg5-spec-value{color:#171717;font-weight:600;text-align:left}
.mg5-spec-actions{display:flex;justify-content:center;gap:18px;padding:0 20px 96px}
.mg5-spec-actions a{display:inline-flex;align-items:center;justify-content:center;gap:10px;min-width:190px;padding:13px 24px;border:1px solid #171717;border-radius:999px;color:#171717!important;font-weight:600;text-decoration:none!important}
.mg5-spec-actions__primary{border-color:#d71920!important;background:#d71920;color:#fff!important}
.mg5-price-section{padding:84px clamp(20px,7vw,104px) 94px;background:#f5f5f5;color:#171717}
.mg5-price-section h2,.mg5-see-heading h2{margin:0;font-size:40px;line-height:1.15}
.mg5-price-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:42px;margin:64px auto 38px;max-width:1120px}
.mg5-price-grid article{min-width:0}
.mg5-price-grid h3{margin:0 0 14px;font-size:18px;font-weight:500}
.mg5-price-grid strong{display:block;font-size:clamp(22px,2.1vw,30px);font-weight:700;white-space:nowrap}
.mg5-price-note{margin:0 0 12px;font-size:14px;font-weight:600}
.mg5-price-disclaimer{max-width:780px;margin:0 auto;color:#686868;font-size:12px;line-height:1.55}
.mg5-see-heading{padding:92px 20px 46px;background:#fff}
#mg5-color-selector{display:grid;grid-template-columns:minmax(230px,25%) minmax(0,75%);align-items:center;column-gap:28px}
#mg5-color-selector .pb-product-color-selector__header{grid-column:1;margin:0;padding:0 0 0 clamp(24px,5.5vw,86px)}
#mg5-color-selector .pb-product-color-selector__body{display:contents}
#mg5-color-selector .pb-product-color-selector__stage{grid-column:2;width:100%;background:transparent}
#mg5-color-selector .pb-product-color-selector__list{grid-column:1 / -1;display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:0;margin-top:34px;padding:0 clamp(22px,6vw,92px)}
#mg5-color-selector .pb-product-color-selector__item{min-width:0!important}
#mg5-color-selector .pb-product-color-selector__swatch{border:1px solid rgba(0,0,0,.16)}
#mg5-color-selector .pb-product-color-selector__copy{align-items:center}
#mg5-color-selector .pb-product-color-selector__item.is-active .pb-product-color-selector__copy strong{color:#171717}
.mg5-service-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:50px;padding:108px clamp(28px,9vw,180px) 128px;background:#fff}
.mg5-service-card{display:flex;min-width:0;flex-direction:column;align-items:center;color:#111!important;text-decoration:none!important}
.mg5-service-card img{width:56px;height:56px;margin-bottom:18px;object-fit:contain}
.mg5-service-card h3{margin:0 0 12px;font-size:22px;font-weight:500;line-height:1.25}
.mg5-service-card span{display:inline-flex;align-items:center;gap:10px;color:#111;font-size:15px;font-weight:600;text-decoration:underline;text-underline-offset:3px}
@media(max-width:900px){
  #mg5-specification,#mg5-price,#mg5-colors,#mg5-services{scroll-margin-top:132px}
  #mg5-specification .pb-feature-showcase__split--hero{min-height:320px}
  #mg5-specification .pb-feature-showcase__metrics{gap:36px}
  #mg5-spec-tabs{width:min(calc(100% - 30px),1296px)}
  .mg5-price-grid{gap:22px}
  #mg5-color-selector{grid-template-columns:minmax(190px,30%) minmax(0,70%)}
  #mg5-color-selector .pb-product-color-selector__header{padding-left:28px}
  .mg5-service-grid{padding-inline:54px}
}
@media(max-width:767px){
  #mg5-specification .pb-feature-showcase__container{padding-top:58px}
  #mg5-specification .pb-feature-showcase__hero-heading{margin-bottom:24px}
  #mg5-specification .pb-feature-showcase__split--hero{min-height:0}
  #mg5-specification .pb-feature-showcase__metrics{grid-template-columns:repeat(2,minmax(0,1fr));width:100%!important;gap:18px}
  #mg5-specification .pb-feature-showcase__metric-value{font-size:clamp(38px,13vw,58px)!important}
  #mg5-spec-tabs{width:calc(100% - 24px);padding-bottom:48px}
  #mg5-spec-tabs .el-tabs-content{padding-top:18px}
  #mg5-spec-tabs .el-widget-accordion__summary{min-height:54px;padding:14px 18px}
  .mg5-spec-row{grid-template-columns:1fr;gap:5px;padding:12px 0}
  .mg5-spec-value{padding-left:27px}
  .mg5-spec-actions{flex-direction:column;align-items:stretch;padding:0 18px 66px}
  .mg5-spec-actions a{width:100%;box-sizing:border-box}
  .mg5-price-section{padding:62px 18px 70px}
  .mg5-price-section h2,.mg5-see-heading h2{font-size:34px}
  .mg5-price-grid{grid-template-columns:1fr;gap:30px;margin:46px auto 32px}
  .mg5-price-grid strong{white-space:normal}
  .mg5-see-heading{padding:66px 18px 34px}
  #mg5-color-selector{display:block;padding:30px 12px 42px!important}
  #mg5-color-selector .pb-product-color-selector__header{margin-bottom:22px;padding:0}
  #mg5-color-selector .pb-product-color-selector__body{display:flex}
  #mg5-color-selector .pb-product-color-selector__list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));margin-top:20px;padding:0}
  #mg5-color-selector .pb-product-color-selector__item:last-child{grid-column:1 / -1}
  .mg5-service-grid{grid-template-columns:1fr;gap:58px;padding:72px 24px 82px}
}
.pb-canvas.is-tablet #mg5-spec-tabs{width:min(calc(100% - 30px),1296px)}
.pb-canvas.is-tablet #mg5-color-selector{grid-template-columns:minmax(190px,30%) minmax(0,70%)}
.pb-canvas.is-tablet .mg5-service-grid{padding-inline:54px}
.pb-canvas.is-mobile #mg5-specification .pb-feature-showcase__split--hero{min-height:0}
.pb-canvas.is-mobile #mg5-spec-tabs{width:calc(100% - 24px);padding-bottom:48px}
.pb-canvas.is-mobile .mg5-spec-row{grid-template-columns:1fr;gap:5px}
.pb-canvas.is-mobile .mg5-spec-value{padding-left:27px}
.pb-canvas.is-mobile .mg5-spec-actions{flex-direction:column;align-items:stretch;padding:0 18px 66px}
.pb-canvas.is-mobile .mg5-price-grid{grid-template-columns:1fr}
.pb-canvas.is-mobile #mg5-color-selector{display:block;padding:30px 12px 42px!important}
.pb-canvas.is-mobile #mg5-color-selector .pb-product-color-selector__header{margin-bottom:22px;padding:0}
.pb-canvas.is-mobile #mg5-color-selector .pb-product-color-selector__body{display:flex}
.pb-canvas.is-mobile #mg5-color-selector .pb-product-color-selector__list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));margin-top:20px;padding:0}
.pb-canvas.is-mobile .mg5-service-grid{grid-template-columns:1fr;gap:58px;padding:72px 24px 82px}

/* MG5 full-width flex item correction */
#mg5-specification,#mg5-spec-tabs,.mg5-spec-actions-widget,.mg5-price-widget,.mg5-see-heading-widget,#mg5-color-selector,.mg5-services-widget{flex:0 0 100%!important;width:100%!important;max-width:none!important;box-sizing:border-box}
#mg5-spec-tabs>.el-widget-tabs__nav,#mg5-spec-tabs>.el-tabs-content{width:min(calc(100% - 40px),1296px);margin-inline:auto;box-sizing:border-box}
@media(max-width:900px){#mg5-spec-tabs>.el-widget-tabs__nav,#mg5-spec-tabs>.el-tabs-content{width:min(calc(100% - 30px),1296px)}}
@media(max-width:767px){#mg5-spec-tabs>.el-widget-tabs__nav,#mg5-spec-tabs>.el-tabs-content{width:calc(100% - 24px)}}
.pb-canvas.is-tablet #mg5-spec-tabs>.el-widget-tabs__nav,.pb-canvas.is-tablet #mg5-spec-tabs>.el-tabs-content{width:min(calc(100% - 30px),1296px)}
.pb-canvas.is-mobile #mg5-spec-tabs>.el-widget-tabs__nav,.pb-canvas.is-mobile #mg5-spec-tabs>.el-tabs-content{width:calc(100% - 24px)}

/* MG5 product color layout correction */
#mg5-color-selector .pb-product-color-selector__body{display:contents!important}
#mg5-color-selector .pb-product-color-selector__stage{grid-column:2!important}
#mg5-color-selector .pb-product-color-selector__list{grid-column:1 / -1!important;display:grid!important;grid-template-columns:repeat(5,minmax(0,1fr))!important;width:100%!important;box-sizing:border-box}
#mg5-color-selector [hidden]{display:none!important}
@media(max-width:767px){#mg5-color-selector .pb-product-color-selector__body{display:flex!important}#mg5-color-selector .pb-product-color-selector__list{grid-template-columns:repeat(2,minmax(0,1fr))!important}}
.pb-canvas.is-mobile #mg5-color-selector .pb-product-color-selector__body{display:flex!important}
.pb-canvas.is-mobile #mg5-color-selector .pb-product-color-selector__list{grid-template-columns:repeat(2,minmax(0,1fr))!important}

/* MG5 accordion visual parity correction */
#mg5-spec-tabs .el-widget-accordion__summary{background:#f4f4f4!important;border-radius:28px!important}
#mg5-spec-tabs .el-widget-accordion__item[open]>.el-widget-accordion__summary{border-radius:28px 28px 0 0!important}
#mg5-spec-tabs .el-widget-accordion__item[open]>.el-widget-accordion__content-wrap{border:1px solid #ededed;border-top:0;border-radius:0 0 22px 22px}
.mg5-service-card h3{font-size:clamp(22px,1.5vw,29px)}

/* MG5 visual parity update: source-backed section adjustments */
#mg5-spec-tabs>.el-widget-tabs__nav,#mg5-spec-tabs>.el-tabs-content{width:min(calc(100% - 10vw),1296px)}
#mg5-spec-tabs .el-widget-tabs__nav{align-items:stretch;justify-content:center}
#mg5-spec-tabs .el-widget-tabs__tab{flex:1 1 0;min-width:0}
.mg5-price-section{width:min(calc(100% - 10vw),1296px);margin-inline:auto;padding:84px 12px 96px;background:#fff;color:#171717;text-align:center;box-sizing:border-box}
.mg5-price-visual{width:min(100%,887px);margin:42px auto 26px}
.mg5-price-visual img{display:block;width:100%;height:auto}
.mg5-price-grid{margin:0 auto 38px;max-width:1120px;text-align:center}
.mg5-price-note{text-align:center}
.mg5-price-disclaimer{max-width:none;text-align:left}
#mg5-color-selector{width:min(calc(100% - 10vw),1296px)!important;margin-inline:auto;background:#fff!important;padding:46px 0 54px!important;grid-template-columns:minmax(230px,25%) minmax(0,75%)}
#mg5-color-selector .pb-product-color-selector__stage{aspect-ratio:1264 / 464!important}
@media(max-width:767px){#mg5-spec-tabs .el-widget-tabs__tab{flex:1 1 0;padding-inline:10px}.mg5-price-section{width:100%;padding:62px 18px 70px}.mg5-price-visual{margin:28px auto 22px}#mg5-color-selector{width:100%!important;padding:30px 12px 42px!important}#mg5-color-selector .pb-product-color-selector__stage{aspect-ratio:16 / 9!important}}
